void Require(bool c,const char* m){if(!c)throw std::runtime_error(m);}
platform::Uuid Nonzero(platform::byte v){platform::Uuid u{};u.bytes[0]=v;u.bytes[6]=0x70;u.bytes[8]=0x80;return u;}
struct CancelAfterCalls{unsigned calls=0;unsigned cancel_on=1;};
bool CancelAtCall(void* context) noexcept {auto* state=static_cast<CancelAfterCalls*>(context);return ++state->calls>=state->cancel_on;}
dt::BitStringDescriptorProfileV3 Profile(){
  const platform::Uuid descriptor{{0x01,0x9d,0,0,0,0,0x70,0,0x80,0,0,0,0,0,0xd8,0x29}};
  const auto historical=dt::LookupDatatypeTypeCodecIdentityV3(dt::kDatatypeCohortV6,6,6,descriptor,1);
  Require(historical.ok&&!dt::IsExactCanonicalBitStringTypeCodecIdentityV3(historical.row),"d706 historical bit identity");
  dt::BitStringProfileRequestV3 historical_request;historical_request.identity=historical.row;historical_request.receipt={Nonzero(6),dt::kDatatypeCohortV6,6,6};Require(!dt::BuildBitStringDescriptorProfileV3(historical_request).ok(),"d706 historical profile refusal");
  for(const auto& row:dt::CurrentDatatypeTypeCodecIdentityRowsV3()) if(dt::IsExactCanonicalBitStringTypeCodecIdentityV3(row)){
    dt::BitStringProfileRequestV3 q; q.identity=row;q.receipt={Nonzero(9),row.legacy_fields.catalog_snapshot_uuid,row.legacy_fields.catalog_generation,row.legacy_fields.registry_generation};
    auto p=dt::BuildBitStringDescriptorProfileV3(q);Require(p.ok(),"profile");return p.profile;
  } throw std::runtime_error("bit identity missing");
}

std::vector<platform::byte> Hex(const char* text){std::vector<platform::byte> out;for(;text[0]&&text[1];text+=2){auto n=[](char c){return c<='9'?c-'0':c-'a'+10;};out.push_back(static_cast<platform::byte>((n(text[0])<<4)|n(text[1])));}return out;}
dt::BitStringValueViewV3 LogicalView(const dt::BitStringDescriptorProfileV3& profile,const char* logical,std::vector<platform::byte>* packed){
  if(std::string_view(logical)=="SQL_NULL")return {&profile,dt::BitStringValueStateV3::sql_null,0,{},dt::BitStringOwnershipV3::borrowed};
  if(std::string_view(logical)=="<empty>")return {&profile,dt::BitStringValueStateV3::present,0,{},dt::BitStringOwnershipV3::borrowed};
  const std::string_view bits(logical);packed->assign((bits.size()+7)/8,0);for(std::size_t i=0;i<bits.size();++i)if(bits[i]=='1')(*packed)[i/8]|=static_cast<platform::byte>(0x80u>>(i%8));
  return {&profile,dt::BitStringValueStateV3::present,static_cast<platform::u32>(bits.size()),*packed,dt::BitStringOwnershipV3::borrowed};
}
