void TestSealedSortKeysAndMaximum(const dt::BitStringDescriptorProfileV3& profile){
  for(const auto& sealed:sealed_keys){std::vector<platform::byte> packed;auto value=LogicalView(profile,sealed.logical,&packed);auto key=dt::MakeBitStringSortKeyV3(value,sealed.direction,sealed.null_mode);Require(key.ok()&&key.bytes==Hex(sealed.hex),"sealed sort key vector");}
  std::vector<platform::byte> maximum(2'097'152,0xff);dt::BitStringValueViewV3 value{&profile,dt::BitStringValueStateV3::present,16'777'216,maximum,dt::BitStringOwnershipV3::borrowed};auto key=dt::MakeBitStringSortKeyV3(value,dt::BitStringSortDirectionV3::ascending,dt::BitStringNullModeV3::nulls_first);Require(key.ok()&&key.bytes.size()==16'777'321,"maximum sort key extent");auto digest=scratchbird::core::hash::ComputeSha256Digest(key.bytes);Require(digest.ok()&&scratchbird::core::hash::HexLower(digest.digest)=="14a4b600b03a9dccaa991026551ca86ea10830affa54cb9f8c507ec9dd9f41fa","maximum sort key recipe");}
