std::array<unsigned,21> metric_observations{};
bool MetricSink(const dt::BitStringMetricRecordV3& e,void*) noexcept {const auto i=static_cast<unsigned>(e.metric);if(i<metric_observations.size())++metric_observations[i];return true;}
dt::BitStringMetricRecordV3 ValidMetricRecord(dt::BitStringMetricV3 metric){
  dt::BitStringMetricRecordV3 r;r.metric=metric;r.database_uuid=Nonzero(20);r.node_uuid=Nonzero(21);r.value=1;r.represented_event_committed=true;
  using M=dt::BitStringMetricV3;
  switch(metric){
    case M::descriptor_admissions:r.result=dt::BitStringMetricResultLabelV3::admitted;break;
    case M::descriptor_refusals:r.reason=dt::BitStringMetricReasonV3::absent;break;
    case M::values_admitted:r.value_state=dt::BitStringMetricValueStateLabelV3::present;break;
    case M::empty_values_admitted:case M::logical_bits:break;
    case M::logical_length:r.update=dt::BitStringMetricUpdateV3::histogram_observe;break;
    case M::owned_bytes:r.update=dt::BitStringMetricUpdateV3::gauge_set;r.allocation_class=dt::BitStringMetricAllocationClassV3::owned_value;break;
    case M::length_refusals:r.operation=dt::BitStringMetricOperationV3::logical_bit_length;break;
    case M::padding_refusals:r.reason=dt::BitStringMetricReasonV3::padding;break;
    case M::canonical_encoding_refusals:r.reason=dt::BitStringMetricReasonV3::trailing;break;
    case M::index_admission_refusals:r.reason=dt::BitStringMetricReasonV3::policy;r.index_family=dt::BitStringMetricIndexFamilyV3::aggregate_sketch;break;
    case M::statistics_stale:r.reason=dt::BitStringMetricReasonV3::stale;break;
    case M::compatibility_mapping_misses:r.reason=dt::BitStringMetricReasonV3::unsupported;r.lane_class=dt::BitStringMetricLaneClassV3::reference_engine_compatibility;break;
    case M::transport_refusals:r.reason=dt::BitStringMetricReasonV3::unsupported;r.lane_class=dt::BitStringMetricLaneClassV3::native_sbwp;break;
    case M::serialization_refusals:r.reason=dt::BitStringMetricReasonV3::profile_missing;r.boundary=dt::BitStringMetricBoundaryV3::component;break;
    case M::protection_refusals:r.reason=dt::BitStringMetricReasonV3::policy;r.layer=dt::BitStringMetricLayerV3::canonical;break;
    case M::merge_manual_review:r.reason=dt::BitStringMetricReasonV3::manual_review;break;
    case M::operation_attempts:r.operation=dt::BitStringMetricOperationV3::validate;break;
    case M::operation_success:r.operation=dt::BitStringMetricOperationV3::hash;break;
    case M::operation_refusals:r.operation=dt::BitStringMetricOperationV3::cast;r.reason=dt::BitStringMetricReasonV3::mismatch;break;
    case M::operation_input_bits:r.update=dt::BitStringMetricUpdateV3::histogram_observe;r.operation=dt::BitStringMetricOperationV3::bit_count;break;
  }
  return r;
}
